  var OPEN_LABEL = { open: '開放的', mid: 'ふつう', shy: '照れ屋' }, JEAL_LABEL = { none: 'なし', one: '片方', both: '両方' }, SHAPE_LABEL = { oneTwo: '攻め×受け・受け', twoOne: '攻め・攻め×受け', sandwich: 'サンドイッチ', ring: '輪' };
