    var P = HK.Pos, pool = P && P.explicit(M) && P.isBottom(M) ? ['oneTwo', 'oneTwo', 'oneTwo', 'sandwich', 'twoOne'] : ['sandwich', 'sandwich', 'twoOne', 'oneTwo'];
    return { p: ctx.rng.pick(pool), t: Tn, m: M, u: Bn };
