  EV.push({ id: 'om_job_p', cat: 'bond', scope: 'pair', when: function (ctx, a, b) { return met(ctx, a, b); }, w: function (ctx, a) { return 1.2 + (a.action.id === 'work' ? 0.4 : 0); }, run: jobRun('p') });

