          ctx.act2({ actors: [silent, asker], cat: 'solo', fx: function () { ctx.mod(asker, silent, { att: 4, trust: -2 }); },
            text: ctx.t('{a}は自分の番が来ても話さなかった。{b}だけが、その横顔をしばらく見ていた。', silent, asker), why: silent.name + 'のドライさ。' + asker.name + 'の関心' });
