  DG.CLIMAX_TOP = [
    L('{a}は奥歯を噛みしめたまま、体の奥の熱に押し流されるように達した。|{a}は荒い息のまま短く震え、すぐに顔を上げた。|{a}は込み上げる熱を抑えきれず、拳を握りしめて達した。'),
    L('{a}は熱を逃がしきれずに達し、悔しげに息を吐いた。|{a}は昂りの頂で震え、乱れた前髪をかき上げた。|{a}は唸るような声を漏らして果てた。'),
    L('{a}は昂りに任せて、深く達した。|{a}は果てたあと、獲物を探すように辺りを見回した。|{a}は熱に浮かされたまま、荒々しく果てた。'),
    L('{a}は満足げに息を吐きながら、深く達した。|{a}は果てたあと、口の端を吊り上げた。|{a}は貪るように昂りを味わい、果てた。'),
    L('{a}は笑いながら、何度目かの絶頂を貪った。|{a}は果ててなお、次の獲物を求めていた。|{a}の昂りは、果てても果てても収まらなかった。')
  ];

  /* 絶頂のときにたまに漏れる短い声（態度ごと） */
