    var will = d.tr.cp * 0.4 + d.tr.a * 0.3 + d.tr.cold * 0.35 + d.tr.aggr * 0.2 + (d.weapon ? d.weapon.pow * 0.05 : 0) - Math.max(0, ctx.R(d, c).aff) / 110 + (prom ? 0.45 : 0);
    var actors = [c].concat(P);
