    var t = '足取り：' + path.join('→') + '　武器：' + wname(c) + (z.kills ? '　倒したゾンビ ' + z.kills + '体' : '');
    if (f && f.pc == null) t += '　家族：' + f.rel + '（' + (f.inside ? '街の中' : '街の外') + (f.found ? '・' + { ok: '合流できた', zombie: 'ゾンビになっていた', dead: '亡くなっていた' }[f.state] : f.heard ? '・悪い知らせが届いた' : '') + '）';
