      if (maxOut && maxIn && maxOut !== maxIn && mo > 25 && mi > 25) p.notes.push(p.name + 'が最も心を寄せたのは' + maxOut.name + 'だが、' + p.name + 'を最も想っていたのは' + maxIn.name + 'だった。');
