    var nAll = S.P.length, sk = skill(p, c.type), ch = (0.07 + sk * 0.42) * (1.5 - nAll * 0.13) + (p.goal.id === 'truth' ? 0.08 : 0) + (night(h) && c.type === 'spirit' ? 0.08 : 0);
