    var fx = HK.weighted(rng, JS.SHRINE_FX, function (f) { return f.w; });
    var t = ST.fmt(ST.pick(S, JS.SHRINE_BREAK), { a: p.name }) + ST.pick(S, JS.SHRINE_SCOLD) + ST.fmt(ST.pick(S, fx.t), { a: p.name });
    if (fx.id === 'curse') p.curse = S.h;
