      var debunk = sharp && rng() < (skill(sharp, 'obs') + skill(sharp, 'lore')) * 0.45 + (sharp.job === 'detective' ? 0.25 : sharp.job === 'sleuth' ? 0.4 : sharp.job === 'ponkotsu' ? -0.3 : 0);
