      (rng() < (S.inCave ? 0.24 : 0.33) + (S.fleeBonus || 0) + (S.fog ? 0.06 : 0) + p.stats.luck * 0.07 + p.stats.stamina * 0.04 - p.m.fear / 400 ? ok : ng).push(p);
