    ST.say(S, { actors: mg === p ? [p] : [mg, p], tag: '退魔', text: t + ST.fmt(ST.pick(S, X.BANISH), { a: mg.name }), why: mg.name + '（術者）が魔術で村人を退けた（儀式の力）', mag: 24 });
    return true;
