    S.host = hosts[0] || { name: rng.pick(Y.HOSTS), npc: true, alive: true, i: null, tr: HK.traits({ CP: 16, NP: 6, A: 14, FC: 8, AC: 6 }), m: {}, cnt: {} };

    /* ---------- 犯人と動機 ---------- */
