    /* 危ない相手：証拠を多く掴んでいる人・探りを入れてきた人・探偵 */
    var danger = function (q) { return q.cnt.clue * 2 + (q.approached ? 3 : 0) + (q.isDet ? 1.5 : 0) + (S.mot.triangle && q === S.x ? -5 : 0); };
    var top = live.slice().sort(function (a, b) { return danger(b) - danger(a); })[0];
