      var sp = k === 'nurse' ? (kd === 'ff' ? R.nurseFf : kd === 'ride' ? R.nurseRide : R.nursePen) : (kd === 'ff' ? R.ff : kd === 'ride' ? R.ride : R.pen);
      /* 女性どうしで秘所を重ねる文は、二人ともリバのときだけ */
