    var civ = S.planet && S.planet.civ.st >= 1 && /primitive|living|advanced|transcendent/.test(S.planet.civ.d.state) && rng() < 0.25;
    var pol = S.planet && S.planet.life.some(function (l) { return l.st >= 1 && l.d.kind === 'plant'; }) && rng() < 0.35;
