    var lover = live.filter(function (q) { return q !== p && JS.alive(q) && !q.bound && JS.REL.bond(S, p, q) >= 0.35 && (HK.canLove ? HK.canLove(q, p) : true) && JS.R18.okPair(p, q); }).sort(function (a, b) { return JS.REL.bond(S, p, b) - JS.REL.bond(S, p, a); })[0];
    mark(p, h);
