  function gp(S, p) { var t = GP[(HK.personaOf ? HK.personaOf(p) : p.persona) || 'gentle'] || GP.gentle; return fmt(ST.pick(S, t), { a: p.name }); }
  /* きっかけごとの言い方（理由の欄）と、媚薬が回っていたときの書き出し */
  var KIND = { d: '夢の中で', r: '村の儀式で', b: '眷属に襲われ', v: '村人たちに襲われ', p: '神に取り憑かれ' };
