      prey = prey || vill.sort(function (a, b) { return (b.acc + (b === seer && seerCO.indexOf(b) >= 0 ? 0.6 : 0) + (medCO.indexOf(b) >= 0 ? 0.3 : 0)) - (a.acc + (a === seer && seerCO.indexOf(a) >= 0 ? 0.6 : 0) + (medCO.indexOf(a) >= 0 ? 0.3 : 0)); })[0];
