    var why = v.name + 'は、人狼の' + w.name + 'を' + (top.fooled ? (c.plan.fake === w ? '本物の占い師' : '本物の霊媒師') + 'だと信じ切っていた' : '最後まで信じていた') + '（信頼 ' + Math.round(top.trust * 100) + (top.close > 0.3 ? '・関係の近さ ' + Math.round(top.close * 100) : '') + (v.ally === w ? '・協力していた' : '') + '）';
